exercises.schema:
CREATE TABLE teams (
  id   int PRIMARY KEY,
  name text NOT NULL
);
CREATE TABLE engineers (
  id      int PRIMARY KEY,
  team_id int NOT NULL REFERENCES teams(id),
  name    text NOT NULL,
  salary  numeric(10,2)
);

